    [6117] = {
        achievementId = 6117,
        name = "Heroic: End Time",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Heroic: End Time",
        difficulty = "easy",
        difficultyReason = "A high-level legacy clear; follow the dungeon's progression events and final-boss requirement.",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A high-level legacy clear; follow the dungeon's progression events and final-boss requirement.\n\n1. Set Dungeon Difficulty to Heroic before entering End Time. A different difficulty or a similarly named raid is not the requested clear.\n\n2. Descend into the Caverns of Time in Tanaris and enter End Time. Use its transit device to visit the TWO randomly selected echo shrines; only those echoes are required for this run.\n\n3. Complete the selected shrine events and defeat both echoes. Azure is Jaina, Ruby is Sylvanas, Obsidian is Baine and Emerald is Tyrande. At Jaina gather the required staff fragments; at Tyrande bring shadow enemies into moonlight until her event opens.\n\n4. Travel to Bronze Dragonshrine and engage Murozond. Use the central Hourglass of Time when needed to rewind the fight and restore resources, then defeat him. Complete the offered quest hand-ins if you need to unlock Well of Eternity afterward.",
        waypoints = {
