    [6128] = {
        achievementId = 6128,
        name = "Ping Pong Champion",
        category = "Raids",
        sourceType = "Achievement",
        source = "Ping Pong Champion",
        difficulty = "hard",
        difficultyReason = "Preserve Zon'ozz while controlling the orb's direction, short immunity and ten-bounce counter.",
        acquisition = "Difficulty: Hard - Preserve Zon'ozz while controlling the orb's direction, short immunity and ten-bounce counter.\n\n1. Enter Dragon Soul on Normal or Heroic and reach Zon'ozz. Remove damaging procs, retaliation and attacking pets. A tank specialization prevents daze while chasing the orb; a second player holding the boss aside makes it easier.\n\n2. Wait for the Void of the Unmaking orb. Run into it to reverse its direction, then continue briefly in your original direction so its transparent immune form can pass through you and the following boss safely.\n\n3. Turn and follow the orb until its center glows again, roughly two to three seconds, then intercept it to bounce it back. Repeat for TEN player bounces. Keep the glowing orb away from the boss and outer wall; either collision can end that sequence. A passive pet or helper can hold Zon'ozz aside instead of following you.\n\n4. Inspect Void Diffusion on the ORB and confirm ten stacks, then kill Zon'ozz. The current counter can cap at ten, so waiting for an eleventh visible stack is unnecessary. If the orb was lost before ten, preserve the boss and try the next orb.",
        stepCount = 4,
        waypoints = {
