    [6133] = {
        achievementId = 6133,
        name = "Maybe He'll Get Dizzy...",
        category = "Raids",
        sourceType = "Achievement",
        source = "Maybe He'll Get Dizzy...",
        difficulty = "hard",
        difficultyReason = "Complete an ordered four-roll sequence and then all three armor plates in the successful Spine attempt.",
        acquisition = "Difficulty: Hard - Complete an ordered four-roll sequence and then all three armor plates in the successful Spine attempt.\n\n1. Enter Dragon Soul on Normal or Heroic and clear through Blackhorn to Spine. Kill three Corruption tentacles and leave one alive. The required sequence is LEFT, RIGHT, LEFT, RIGHT; warnings alone do not count as completed rolls.\n\n2. Stand in a dead tentacle hole on the LEFT and verify Grasping Tendrils anchors you while Deathwing completes a left roll. Move to a RIGHT-side hole for the next completed roll, then repeat LEFT and RIGHT. Keep yourself anchored during each completed roll so you are not thrown off.\n\n3. On Spine, kill three Corruption tentacles and leave one alive. Anchor in a dead tentacle's hole with Grasping Tendrils for a planned roll to discard unwanted Amalgamations. Kill Corrupted Bloods, keep ONE Hideous Amalgamation alive and lead it across the blood residue until its Absorbed Blood is at NINE stacks. Current Heroic can supply all nine from a single residue, so inspect its buff rather than counting nine bodies.\n\n4. Bring that nine-stack Amalgamation directly against the next HEADWARD armor plate, then kill it there. Its Nuclear Blast lifts the plate: immediately kill the exposed Burning Tendon. Repeat for all three plates. Between planned rolls, alternate left/right to cancel the roll warning or remain anchored in a hole; an unanchored completed roll throws you off. Once the required four rolls are complete, avoid unnecessary extra completed rolls while opening the plates. The achievement requires successfully finishing Spine after the sequence; resetting or falling off means starting the sequence again.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 71,
                x = 0.644,
                y = 0.5,
                step = 1,
                label = "Caverns of Time - descend to Dragon Soul",
                mapName = "Tanaris",
