    [6181] = {
        achievementId = 6181,
        name = "Fangs of the Father",
        category = "Collections",
        sourceType = "Achievement",
        source = "Fangs of the Father",
        difficulty = "hard",
        difficultyReason = "Rogue-only stealth missions, two long raid collection stages and Spine's scripted mechanics.",
        stepCount = 14,
        acquisition = "Difficulty: Hard - Rogue-only stealth missions, two long raid collection stages and Spine's scripted mechanics.\n\n1. Use a Rogue of at least level 35. Enter original Dragon Soul inside the Caverns of Time in Tanaris on NORMAL or HEROIC; Raid Finder cannot provide the quest items. Accept Proving Your Worth from Lord Afrasastrasz inside the raid near the starting Wyrmrest area. Outdoor Dragonblight's Wyrmrest Temple is the wrong instance.\n\n2. Defeat Morchok, Zon'ozz and Yor'sahj, then use the temple transports and Eye of Eternity portal for Hagara. Clear her preceding waves. When she lands and waits in the middle, approach in Stealth and PICK POCKET her for Cryptomancer's Decoder Ring BEFORE killing her. Return to the quest giver; if her pocket is empty, reset her encounter safely and try again.\n\n3. Accept A Hidden Message. Visit Thaumaturge Rafir in Stormwind (50.6, 61.3) or Thaumaturge Altha in Orgrimmar (57.6, 65.5), pay TEN THOUSAND gold and receive the Charging Decoder Ring. Wait TWELVE real hours; you can be logged out. This timer is not twelve hours of played time.\n\n4. Go to Corastrasza beneath the large tree at Vermillion Redoubt in Twilight Highlands (29.0, 25.0). Obtain Singed Cipher and use your CHARGED ring to decode it. Turn in, accept To Ravenholdt and speak to Mostrasz outside for the flight.\n\n5. Complete To Catch a Thief by following the special stealth route into Ravenholdt Manor. Use the supplied detection guidance to avoid guards and enter as directed. Ordinary Ravenholdt reputation does not make these quest guards friendly. Meet Wrathion in the cellar and follow the dialogue.\n\n6. Follow Our Man in Gilneas to Zazzo and complete Assassinate Creed. Use Zazzo's quest transport/instructions to reach the mission phase, sneak through the guarded town, kill Lord Hiram Creed and return to Ravenholdt. Turn in The Deed is Done for Fear and Vengeance, the FIRST dagger pair; keep both for later upgrades.\n\n7. Accept Cluster Clutch. Return to Dragon Soul each weekly reset, loot Elementium Gem Clusters from eligible bosses, and OPEN them until you have THREE HUNDRED THIRTY-THREE Shadowy Gems. Use 25-player mode for the larger cluster supply. Normal and Heroic share the Dragon Soul boss lockout; changing difficulty is not a second weekly farm. Stop opening clusters when the gem target is reached and keep extra INTACT clusters.\n\n8. Return to Wrathion, then complete Our Man in Karazhan and Blood of the Betrayer. Meet Zazzo outside original Karazhan, enter the quest's cellar mission and defeat Nalice, using the mission's arcane devices to remove her barriers. Return for Victory in the Depths and exchange the first pair for The Sleeper and The Dreamer.\n\n9. Accept Sharpening Your Fangs and collect SIXTY INTACT Elementium Gem Clusters from Dragon Soul bosses over weekly resets. Leftover unopened clusters from the first collection count; loose Shadowy Gems do not replace clusters. Check every boss and loot cache. Raid Finder supplies none.\n\n10. As soon as you reach sixty clusters, leave the raid and turn in to Wrathion BEFORE killing Madness of Deathwing. Accept Patricide and keep the intermediate daggers for its turn-in. If your sixtieth cluster came from Madness itself, you need another eligible weekly kill for the new quest.\n\n11. Continue the raid through Ultraxion and Warmaster Blackhorn. On Spine, kill three Corruption tentacles and anchor in a dead tentacle's hole for a roll to discard unwanted Amalgamations. Keep one Amalgamation, kill Bloods and lead it over residue until its Absorbed Blood reaches NINE. Keep checking the actual stack count.\n\n12. Move the nine-stack Amalgamation against the next armor plate toward Deathwing's head and kill it. Nuclear Blast exposes a Burning Tendon: kill that tendon to remove the plate. Repeat for all THREE plates. Alternate sides to cancel unwanted rolls, or stay anchored; an unanchored completed roll throws you off.\n\n13. At Madness, speak to Thrall, cross the four Aspect platforms and defeat each limb/Mutated Corruption. Return to the starting platform, defeat Deathwing's head and loot the final cache for Fragment of Deathwing's Jaw while Patricide is ACTIVE.\n\n14. Return to Wrathion in Ravenholdt Manor (71.4, 45.5 in Hillsbrad), turn in the jaw and required intermediate weapons, and receive BOTH Golad and Tiriosh together. Finish the scene and check Fangs of the Father. If you deleted an intermediate pair, ask the Ravenholdt NPC for replacements before assuming the chain is blocked.",
        waypoints = {
            { mapID = 71, x = 0.644, y = 0.5, step = 1, label = "Caverns of Time - descend to Dragon Soul" },
            { mapID = 409, x = 0.504, y = 0.6925, step = 2, label = "Morchok - first raid boss", mapName = "Dragon Soul" },
            {
                mapID = 412,
                x = 0.5275,
                y = 0.5205,
                step = 2,
                label = "Hagara - PICK POCKET before killing",
                mapName = "Eye of Eternity - Dragon Soul",
            },
            { mapID = 84, x = 0.506, y = 0.613, step = 3, label = "Thaumaturge Rafir - 10,000-gold decoder charge" },
            {
                mapID = 85,
                x = 0.5760000000000001,
                y = 0.655,
                step = 3,
                label = "Thaumaturge Altha - 10,000-gold decoder charge",
            },
            { mapID = 241, x = 0.29, y = 0.25, step = 4, label = "Corastrasza - cipher / Mostrasz flight" },
            { mapID = 25, x = 0.7140000000000001, y = 0.455, step = 5, label = "Ravenholdt Manor - quest cellar" },
            { mapID = 71, x = 0.644, y = 0.5, step = 7, label = "Dragon Soul - 333 Shadowy Gems" },
            { mapID = 42, x = 0.47, y = 0.75, step = 8, label = "Original Karazhan approach - Zazzo's cellar mission" },
            { mapID = 71, x = 0.644, y = 0.5, step = 9, label = "Dragon Soul - 60 intact clusters" },
            { mapID = 25, x = 0.7140000000000001, y = 0.455, step = 10, label = "Wrathion - accept Patricide BEFORE Madness" },
            { mapID = 25, x = 0.7140000000000001, y = 0.455, step = 14, label = "Wrathion - final legendary pair" },
        },
        sources = {
